// Tópico: invernadero/sensores/<sensor>   —   payload: número como texto
const sensor = msg.topic.split('/').pop();
const valor = parseFloat(msg.payload);
if (isNaN(valor)) {
    node.warn(`Lectura inválida en ${msg.topic}: ${msg.payload}`);
    return null;
}
// Última lectura de cada sensor (la usa la API GET /invernadero/estado)
const lecturas = flow.get('lecturas') || {};
lecturas[sensor] = { valor: valor, fecha: new Date().toISOString() };
flow.set('lecturas', lecturas);

msg.sensor = sensor;
msg.payload = valor;
node.status({ fill: 'green', shape: 'dot', text: `${sensor}: ${valor}` });
return msg;

msg.topic = 'INSERT INTO lecturas (sensor, valor) VALUES (?, ?)';
msg.payload = [msg.sensor, msg.payload];
return msg;

// Reglas con histéresis: el umbral para PRENDER es distinto al de APAGAR,
// así el actuador no se prende y apaga a cada rato.
if ((flow.get('modo') || 'auto') !== 'auto') return null;   // en modo manual no decide

const cfg = Object.assign(
    { suelo_min: 30, suelo_max: 60, temp_max: 32, temp_ok: 28 },
    flow.get('config') || {}
);
const act = flow.get('actuadores') || { riego: 'OFF', ventilador: 'OFF' };
const v = msg.payload;
let orden = null;

if (msg.sensor === 'humedad_suelo') {
    if (v < cfg.suelo_min && act.riego !== 'ON')
        orden = { actuador: 'riego', estado: 'ON', motivo: `Humedad del suelo ${v}% < ${cfg.suelo_min}%` };
    else if (v > cfg.suelo_max && act.riego !== 'OFF')
        orden = { actuador: 'riego', estado: 'OFF', motivo: `Humedad del suelo ${v}% > ${cfg.suelo_max}%` };
}
if (msg.sensor === 'temperatura') {
    if (v > cfg.temp_max && act.ventilador !== 'ON')
        orden = { actuador: 'ventilador', estado: 'ON', motivo: `Temperatura ${v}°C > ${cfg.temp_max}°C` };
    else if (v < cfg.temp_ok && act.ventilador !== 'OFF')
        orden = { actuador: 'ventilador', estado: 'OFF', motivo: `Temperatura ${v}°C < ${cfg.temp_ok}°C` };
}
if (!orden) return null;
orden.origen = 'auto';
return { payload: orden };

const cfg = Object.assign({ temp_alerta: 38, suelo_critico: 15 }, flow.get('config') || {});
const v = msg.payload;

if (msg.sensor === 'temperatura' && v >= cfg.temp_alerta) {
    return { payload: {
        tipo: 'temperatura_critica', sensor: msg.sensor, valor: v, umbral: cfg.temp_alerta,
        mensaje: `🔥 Temperatura crítica en el invernadero: ${v} °C (límite ${cfg.temp_alerta} °C)`
    } };
}
if (msg.sensor === 'humedad_suelo' && v <= cfg.suelo_critico) {
    return { payload: {
        tipo: 'suelo_seco', sensor: msg.sensor, valor: v, umbral: cfg.suelo_critico,
        mensaje: `💧 Sustrato muy seco: ${v} % (mínimo ${cfg.suelo_critico} %). Revisar la bomba de riego.`
    } };
}
return null;

// msg.payload = { actuador, estado, origen, motivo }
const o = msg.payload;
const act = flow.get('actuadores') || { riego: 'OFF', ventilador: 'OFF' };
act[o.actuador] = o.estado;
flow.set('actuadores', act);

node.status({
    fill: (act.riego === 'ON' || act.ventilador === 'ON') ? 'blue' : 'grey',
    shape: 'dot', text: `riego ${act.riego} · ventilador ${act.ventilador}`
});

const comando = { topic: `invernadero/actuadores/${o.actuador}`, payload: o.estado, qos: 1, retain: true };
const estado  = { topic: 'invernadero/estado/actuadores', payload: JSON.stringify(act), qos: 1, retain: true };
const sql = {
    topic: 'INSERT INTO eventos (actuador, estado, origen, motivo) VALUES (?, ?, ?, ?)',
    payload: [o.actuador, o.estado, o.origen, o.motivo || null]
};
return [[comando, estado], sql];

// invernadero/control/modo         auto | manual
// invernadero/control/riego        ON | OFF   (solo en modo manual)
// invernadero/control/ventilador   ON | OFF   (solo en modo manual)
const destino = msg.topic.split('/')[2];
const valor = String(msg.payload).trim();

if (destino === 'modo') {
    const modo = valor.toLowerCase() === 'manual' ? 'manual' : 'auto';
    flow.set('modo', modo);
    node.status({ fill: modo === 'auto' ? 'green' : 'yellow', shape: 'ring', text: 'Modo ' + modo });
    return [{ topic: 'invernadero/estado/modo', payload: modo, qos: 1, retain: true }, null];
}
if (destino === 'riego' || destino === 'ventilador') {
    if ((flow.get('modo') || 'auto') !== 'manual') {
        node.warn('Comando ignorado: el sistema está en modo automático. Pasalo a manual desde el dashboard.');
        return null;
    }
    const estado = valor.toUpperCase() === 'ON' ? 'ON' : 'OFF';
    return [null, { payload: { actuador: destino, estado: estado, origen: 'manual',
                               motivo: 'Comando desde el dashboard' } }];
}
return null;

// Al reiniciar Node-RED, el broker le devuelve el último estado retenido.
const clave = msg.topic.split('/')[2];
if (clave === 'modo') {
    flow.set('modo', String(msg.payload).trim() === 'manual' ? 'manual' : 'auto');
} else if (clave === 'actuadores') {
    try {
        const act = JSON.parse(msg.payload);
        flow.set('actuadores', Object.assign({ riego: 'OFF', ventilador: 'OFF' }, act));
    } catch (e) {
        node.warn('Estado retenido inválido: ' + msg.payload);
    }
}
return null;

if (!flow.get('modo')) flow.set('modo', 'auto');
if (!flow.get('actuadores')) flow.set('actuadores', { riego: 'OFF', ventilador: 'OFF' });
return [[
    { topic: 'invernadero/estado/modo', payload: flow.get('modo'), qos: 1, retain: true },
    { topic: 'invernadero/estado/actuadores', payload: JSON.stringify(flow.get('actuadores')), qos: 1, retain: true }
]];

// El simulador deja como "última voluntad" el mensaje "offline".
// Si el proceso se corta, el broker lo publica y acá se genera la alerta.
if (msg.retain) return null;            // ignorar el estado viejo al reconectar
if (String(msg.payload).trim() !== 'offline') return null;
return { payload: {
    tipo: 'sensores_desconectados', sensor: null, valor: null, umbral: null,
    mensaje: '⚠️ Se perdió la conexión con los sensores del invernadero (última voluntad MQTT).'
} };

// Anti-spam: una alerta del mismo tipo cada X minutos (tabla configuracion)
const a = msg.payload;
const cfg = flow.get('config') || {};
const esperaMs = (cfg.alerta_minutos ?? 10) * 60 * 1000;
const ultimas = flow.get('ultimasAlertas') || {};
const ahora = Date.now();
if (ultimas[a.tipo] && ahora - ultimas[a.tipo] < esperaMs) return null;
ultimas[a.tipo] = ahora;
flow.set('ultimasAlertas', ultimas);

a.fecha = new Date().toISOString();
a.modo = flow.get('modo') || 'auto';
a.actuadores = flow.get('actuadores') || { riego: 'OFF', ventilador: 'OFF' };

const webhook = {
    url: env.get('N8N_WEBHOOK_URL') || 'http://127.0.0.1:5678/webhook/invernadero-alerta',
    headers: { 'Content-Type': 'application/json' },
    payload: a
};
const sql = {
    topic: 'INSERT INTO alertas (tipo, sensor, valor, mensaje) VALUES (?, ?, ?, ?)',
    payload: [a.tipo, a.sensor, a.valor, a.mensaje]
};
node.status({ fill: 'red', shape: 'dot', text: `${a.tipo} · ${new Date().toLocaleTimeString()}` });
return [webhook, sql];

if (!Array.isArray(msg.payload)) return null;
const cfg = {};
for (const fila of msg.payload) cfg[fila.parametro] = Number(fila.valor);
flow.set('config', cfg);
node.status({ fill: 'green', shape: 'dot',
              text: `${Object.keys(cfg).length} parámetros · ${new Date().toLocaleTimeString()}` });
return null;

msg.headers = { 'Access-Control-Allow-Origin': '*' };
msg.payload = {
    fecha: new Date().toISOString(),
    modo: flow.get('modo') || 'auto',
    lecturas: flow.get('lecturas') || {},
    actuadores: flow.get('actuadores') || { riego: 'OFF', ventilador: 'OFF' },
    umbrales: flow.get('config') || {}
};
return msg;

msg.topic = `SELECT sensor,
                    ROUND(MIN(valor), 1) AS minimo,
                    ROUND(MAX(valor), 1) AS maximo,
                    ROUND(AVG(valor), 1) AS promedio,
                    COUNT(*)             AS lecturas
               FROM lecturas
              WHERE fecha >= NOW() - INTERVAL 24 HOUR
              GROUP BY sensor`;
msg.payload = [];
return msg;

msg.sensores = msg.payload;
msg.topic = `SELECT actuador AS item, COUNT(*) AS cantidad
               FROM eventos
              WHERE estado = 'ON' AND fecha >= NOW() - INTERVAL 24 HOUR
              GROUP BY actuador
             UNION ALL
             SELECT 'alertas', COUNT(*)
               FROM alertas
              WHERE fecha >= NOW() - INTERVAL 24 HOUR`;
msg.payload = [];
return msg;

const sensores = {};
for (const s of msg.sensores || []) {
    sensores[s.sensor] = {
        minimo: Number(s.minimo), maximo: Number(s.maximo),
        promedio: Number(s.promedio), lecturas: Number(s.lecturas)
    };
}
const conteo = {};
for (const f of msg.payload || []) conteo[f.item] = Number(f.cantidad);

msg.headers = { 'Access-Control-Allow-Origin': '*' };
msg.payload = {
    periodo: 'últimas 24 horas',
    generado: new Date().toISOString(),
    sensores: sensores,
    encendidos: { riego: conteo.riego || 0, ventilador: conteo.ventilador || 0 },
    alertas: conteo.alertas || 0
};
delete msg.sensores;
return msg;

msg.statusCode = 500;
msg.payload = { error: 'No se pudo consultar la base de datos',
                detalle: msg.error && msg.error.message };
return msg;
